-- SCH-1 group 3 — tenant legal identity and public profile as branding columns.
-- Were settings `branding.legal` {legalForm, nif, rccm, taxRegime, address} and
-- `branding.public_profile` {languages, contact{phone, email, address, website}} (TENANT scope,
-- PLATFORM scope as fallback). The raison sociale stays tenants.legal_name.
-- Section 1 is generated by Prisma; sections 2+ are hand-written.

-- ─────────────────────────── 1. DDL (prisma migrate diff) ───────────────────────────
-- AlterTable
ALTER TABLE "branding" ADD COLUMN     "legal_address" VARCHAR(300),
ADD COLUMN     "legal_form" VARCHAR(100),
ADD COLUMN     "public_contact" JSONB,
ADD COLUMN     "public_languages" TEXT[] DEFAULT ARRAY['fr']::TEXT[],
ADD COLUMN     "rccm" VARCHAR(50),
ADD COLUMN     "tax_id" VARCHAR(50),
ADD COLUMN     "tax_regime" VARCHAR(100);

-- ─────────────────────────── 2. Data migration ───────────────────────────
-- Tenants having settings but no branding row get one (RLS is bypassed by the owner role).
INSERT INTO "branding" (id, tenant_id, updated_at)
SELECT DISTINCT ON (s.tenant_id) gen_random_uuid(), s.tenant_id, now()
  FROM "settings" s
 WHERE s.scope = 'TENANT' AND s.key IN ('branding.legal', 'branding.public_profile')
   AND s.tenant_id IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM "branding" b WHERE b.tenant_id = s.tenant_id);

WITH platform AS (
  SELECT (SELECT value FROM "settings" WHERE scope = 'PLATFORM' AND key = 'branding.legal' LIMIT 1) AS legal,
         (SELECT value FROM "settings" WHERE scope = 'PLATFORM' AND key = 'branding.public_profile' LIMIT 1) AS profile
), src AS (
  SELECT b.id,
         COALESCE((SELECT value FROM "settings" s WHERE s.scope = 'TENANT' AND s.tenant_id = b.tenant_id AND s.key = 'branding.legal' LIMIT 1), p.legal) AS legal,
         COALESCE((SELECT value FROM "settings" s WHERE s.scope = 'TENANT' AND s.tenant_id = b.tenant_id AND s.key = 'branding.public_profile' LIMIT 1), p.profile) AS profile
    FROM "branding" b CROSS JOIN platform p
)
UPDATE "branding" b SET
  legal_form    = left(NULLIF(btrim(src.legal->>'legalForm'), ''), 100),
  tax_id        = left(NULLIF(btrim(src.legal->>'nif'), ''), 50),
  rccm          = left(NULLIF(btrim(src.legal->>'rccm'), ''), 50),
  tax_regime    = left(NULLIF(btrim(src.legal->>'taxRegime'), ''), 100),
  legal_address = left(NULLIF(btrim(src.legal->>'address'), ''), 300),
  public_languages = COALESCE(
    (SELECT array_agg(DISTINCT l) FROM jsonb_array_elements_text(
       CASE WHEN jsonb_typeof(src.profile->'languages') = 'array' THEN src.profile->'languages' ELSE '[]'::jsonb END) AS l
      WHERE l <> ''),
    ARRAY['fr']),
  public_contact = CASE WHEN jsonb_typeof(src.profile->'contact') = 'object'
    THEN jsonb_strip_nulls(jsonb_build_object(
      'phone', src.profile->'contact'->>'phone', 'email', src.profile->'contact'->>'email',
      'address', src.profile->'contact'->>'address', 'website', src.profile->'contact'->>'website'))
    END
  FROM src
 WHERE src.id = b.id AND (src.legal IS NOT NULL OR src.profile IS NOT NULL);
UPDATE "branding" SET public_contact = NULL WHERE public_contact = '{}'::jsonb;

DELETE FROM "settings" WHERE key IN ('branding.legal', 'branding.public_profile');

-- ─────────────────────────── 3. Integrity ───────────────────────────
UPDATE "branding" SET public_languages = ARRAY['fr'] WHERE public_languages IS NULL OR cardinality(public_languages) = 0;
ALTER TABLE "branding" ADD CONSTRAINT branding_public_languages_check
  CHECK (public_languages IS NOT NULL AND cardinality(public_languages) >= 1);
ALTER TABLE "branding" ADD CONSTRAINT branding_public_contact_check
  CHECK (public_contact IS NULL OR jsonb_typeof(public_contact) = 'object');
